const results = await browserjs(tabId, () => {
  const items = [];
  document.querySelectorAll('a').forEach(a => {
    const href = a.href;
    const text = a.innerText.trim();
    if (href && (href.startsWith('http')) && !href.includes('google.com') && text) {
      items.push({ text: text.replace(/\n+/g, ' - '), href });
    }
  });
  return items;
});
console.log("Found links:", results.length);
