const tabId = 787784496;
const dead = await browserjs(tabId, async () => {
  const resp = await fetch('https://ei.jhu.edu/admissions/');
  const text = await resp.text();
  const doc = new DOMParser().parseFromString(text, 'text/html');
  const bodyText = doc.body.innerText;
  const match = bodyText.match(/deadline[^\n]*\n[^\n]*/gi);
  return match || "No deadline found on admissions page";
});
console.log("JHU deadline matches:", dead);

