  { name: "Cooper Union STEM", url: "https://cooper.edu/engineering/stem/summer" },
  { name: "Brown Summer@Brown", url: "https://precollege.brown.edu/programs/summerbrown" },
  { name: "Harvard Pre-College", url: "https://summer.harvard.edu/high-school-programs/pre-college-program/" }
];

const results = [];
for (const c of candidates) {
  try {
    const res = await tool.fetch_url({ url: c.url, method: "GET" });
    results.push({ name: c.name, status: res.status, url: c.url });
  } catch (e) {
    results.push({ name: c.name, error: e.message, url: c.url });
  }
}
console.log(JSON.stringify(results, null, 2));

