  const resp = await fetch('https://precollege.brown.edu/apply');
  const html = await resp.text();
  const doc = new DOMParser().parseFromString(html, 'text/html');
  const main = doc.querySelector('main') || doc.body;
  const match = main.innerText.match(/(deadline|priority)[^\n]*/gi);
  return match;
});
console.log("Brown deadlines:", text);

